/** Tool call shape used by legacy scorer-first APIs. */
type ToolCall = {
    name: string;
    arguments?: unknown;
};
/** Legacy task result that can include assistant text and tool calls. */
type TaskResult = {
    result: string;
    toolCalls?: ToolCall[];
};
/** Legacy task function invoked by scorer-first eval suites. */
type TaskFn = (input: string) => Promise<string | TaskResult>;
/** Legacy score payload returned by scorer functions. */
type Score = {
    score: number | null;
    metadata?: {
        rationale?: string;
        output?: unknown;
    } & Record<string, unknown>;
};
/** Base input supplied to every legacy scorer function. */
interface BaseScorerOptions {
    input: string;
    output: string;
    toolCalls?: ToolCall[];
}
/** Legacy scorer function signature. */
type ScoreFn<TOptions extends BaseScorerOptions = BaseScorerOptions> = (opts: TOptions) => Promise<Score> | Score;

export type { BaseScorerOptions, Score, ScoreFn, TaskFn, TaskResult, ToolCall };
